"""Prototype of math_verify.parser.

Only enough of the latex/expr machinery to exercise the timeout plumbing; the
StringExtractionConfig path is full fidelity.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any, Literal, Sequence

from latex2sympy2_extended import NormalizationConfig, latex2sympy
from latex2sympy2_extended.latex2sympy2 import ConversionConfig
from sympy.parsing.sympy_parser import parse_expr  # module-level -> patchable

from mv_proto.errors import TimeoutException
from mv_proto.utils import timeout

# ---------------------------------------------------------------- configs ---


@dataclass(frozen=True)
class ExtractionConfig:
    try_extract_without_anchor: bool = True


@dataclass(frozen=True)
class LatexExtractionConfig(ExtractionConfig):
    try_extract_without_anchor: bool = True
    boxed_match_priority: int = 55
    normalization_config: NormalizationConfig = field(
        default_factory=lambda: NormalizationConfig(
            basic_latex=True,
            units=True,
            malformed_operators=True,
            nits=True,
            boxed="all",
            equations=False,
        )
    )


@dataclass(frozen=True)
class ExprExtractionConfig(ExtractionConfig):
    try_extract_without_anchor: bool = True


@dataclass(frozen=True)
class StringExtractionConfig(ExtractionConfig):
    strings: tuple[str, ...] = ("A", "B", "C", "D")
    try_extract_without_anchor: bool = True
    lowercase: bool = True


# ------------------------------------------------------- string patterns ---

# Any of the configured strings, delimited so that "B" does not match inside
# "Because".  Fixed-width lookbehind keeps this legal in `re`.
_NOT_WORD_BEFORE = r"(?<![A-Za-z0-9_])"
_NOT_WORD_AFTER = r"(?![A-Za-z0-9_])"

# Words that may introduce the answer, plus the optional copula/punctuation.
_ANSWER_ANCHOR = (
    r"(?i:answer|answers|option|choice)s?\s*"
    r"(?:\bis\b|\bare\b|\bshould\s+be\b|\bwould\s+be\b|\bto\s+be\b|:|=|-{1,2}>?|→)?\s*"
)
# Optional surrounding bracket/paren/quote around the letter itself.
_OPEN = r"[\(\[\{\"'*]*\s*"
_CLOSE = r"\s*[\)\]\}\"'*.]*"


def string_patterns(config: StringExtractionConfig) -> list[tuple[str, int]]:
    """(regex, local-priority) pairs for a :class:`StringExtractionConfig`.

    Lower priority number wins.  Three tiers:

    0 - anchored:      "... the answer is A."
    1 - leading token: "A. Because B is not valid"   (position beats mention)
    2 - bare mention:  "Because B is valid"          (only when
                       ``try_extract_without_anchor``)
    """
    alt = "|".join(re.escape(s) for s in config.strings)
    letter = rf"{_NOT_WORD_BEFORE}(?P<string>{alt}){_NOT_WORD_AFTER}"

    anchored = rf"{_ANSWER_ANCHOR}{_OPEN}{letter}{_CLOSE}"
    # Leading token must be followed by punctuation or end-of-string so that
    # "A number of ..." is not read as the answer "A".
    leading = rf"\A\s*{_OPEN}{letter}\s*[\)\]\}}]?\s*(?=[.,:;)\]\}}\-–—]|$)"
    bare = letter

    patterns = [(anchored, 0), (leading, 1)]
    if config.try_extract_without_anchor:
        patterns.append((bare, 2))
    return patterns


def expr_patterns(config: ExprExtractionConfig) -> list[tuple[str, int]]:
    number = r"(?P<expr>-?\s*(?:\d+(?:[,.\s]\d{3})*(?:[.,]\d+)?|\.\d+)\s*(?:[-+*/^]\s*\d+)*)"
    return [(number, 100)]


def latex_patterns(config: LatexExtractionConfig) -> list[tuple[str, int]]:
    boxed = r"\\boxed\{(?P<latex>(?:[^{}]|\{[^{}]*\})*)\}"
    dollars = r"\$(?P<latex>[^$]+)\$"
    return [(boxed, config.boxed_match_priority), (dollars, 50)]


def get_extraction_regexes(
    extraction_config: Sequence[ExtractionConfig],
) -> list[tuple[re.Pattern, int, ExtractionConfig]]:
    out: list[tuple[re.Pattern, int, ExtractionConfig]] = []
    for idx, cfg in enumerate(extraction_config):
        if isinstance(cfg, StringExtractionConfig):
            pats = string_patterns(cfg)
        elif isinstance(cfg, LatexExtractionConfig):
            pats = latex_patterns(cfg)
        else:
            pats = expr_patterns(cfg)
        for pat, prio in pats:
            if prio < 0:
                continue  # disabled (e.g. boxed_match_priority=-1)
            out.append((re.compile(pat, re.DOTALL), prio + 1000 * idx, cfg))
    return out


# -------------------------------------------------------------- matching ---


def _convert(match: re.Match, cfg: ExtractionConfig) -> tuple[Any, str] | None:
    gd = match.groupdict()
    if isinstance(cfg, StringExtractionConfig):
        raw = gd["string"]
        return (raw.lower() if cfg.lowercase else raw), raw
    if isinstance(cfg, LatexExtractionConfig):
        raw = gd["latex"]
        return latex2sympy(
            raw,
            normalization_config=cfg.normalization_config,
            conversion_config=ConversionConfig(interpret_simple_eq_as_assignment=True),
        ), raw
    raw = gd["expr"]
    cleaned = raw.replace(" ", "").replace(",", "")
    return parse_expr(cleaned, evaluate=True), raw


def extract_target_from_pred(
    pred: str,
    target_res: list[tuple[re.Pattern, int, ExtractionConfig]],
    fallback_mode: str = "first_match",
    extraction_mode: str = "any_match",
    prefer_last: bool = True,
) -> list:
    found: list[tuple[int, int, re.Match, ExtractionConfig]] = []
    for regex, prio, cfg in target_res:
        for m in regex.finditer(pred):
            tie = -m.start() if prefer_last else m.start()
            found.append((prio, tie, m, cfg))
    if not found:
        return []
    found.sort(key=lambda t: (t[0], t[1]))
    if extraction_mode == "first_match":
        found = found[:1]

    for _, _, m, cfg in found:
        try:
            converted = _convert(m, cfg)
        except TimeoutException:
            raise
        except Exception:
            converted = None
        if converted is not None:
            return [converted[0], converted[1]]

    if fallback_mode == "first_match":
        first = found[0][2]
        raw = next(v for v in first.groupdict().values() if v is not None)
        return [raw, raw]
    return []


def parse(
    pred: str,
    extraction_config: Sequence[ExtractionConfig] | None = None,
    fallback_mode: Literal["no_fallback", "first_match"] = "first_match",
    extraction_mode: Literal["first_match", "any_match"] = "any_match",
    parsing_timeout: int | None = 5,
) -> list:
    if extraction_config is None:
        extraction_config = [LatexExtractionConfig(), ExprExtractionConfig()]
    try:
        target_res = get_extraction_regexes(extraction_config)
        return timeout(timeout_seconds=parsing_timeout)(extract_target_from_pred)(
            pred, target_res, fallback_mode, extraction_mode
        )
    except TimeoutException:
        return []
    except Exception:
        return []
