"""Prototype of math_verify.grader."""

from __future__ import annotations

from typing import Any

import sympy

from mv_proto.errors import TimeoutException
from mv_proto.utils import timeout


def sympy_expr_eq(
    gold: Any,
    target: Any,
    float_rounding: int = 6,
    numeric_precision: int = 15,
    allow_set_relation_comp: bool = False,
    strict: bool = True,
) -> bool:
    if gold is target:
        return True
    if isinstance(gold, str) or isinstance(target, str):
        return str(gold) == str(target)
    try:
        return bool(sympy.simplify(gold - target) == 0)
    except Exception:
        return gold == target


def verify(
    gold: Any,
    target: Any,
    float_rounding: int = 6,
    numeric_precision: int = 15,
    strict: bool = True,
    allow_set_relation_comp: bool = False,
    timeout_seconds: int | None = 5,
) -> bool:
    def compare_single(g, t) -> bool:
        # NOTE: sympy_expr_eq is resolved as a *module global* at call time so
        # unittest.mock.patch("math_verify.grader.sympy_expr_eq") takes effect.
        return sympy_expr_eq(
            g,
            t,
            float_rounding=float_rounding,
            numeric_precision=numeric_precision,
            allow_set_relation_comp=allow_set_relation_comp,
            strict=strict,
        )

    if timeout_seconds is not None:
        compare_single = timeout(timeout_seconds=timeout_seconds)(compare_single)

    if not isinstance(gold, list):
        gold = [gold]
    if not isinstance(target, list):
        target = [target]

    try:
        for g in gold:
            for t in target:
                try:
                    if compare_single(g, t):
                        return True
                except TimeoutException:
                    raise
                except Exception:
                    continue
        return False
    except TimeoutException:
        return False
