"""Prototype of math_verify.metric."""

from __future__ import annotations

from typing import Callable, Literal, Sequence

from mv_proto.parser import ExtractionConfig, parse
from mv_proto.grader import verify


def math_metric(
    gold_extraction_target: Sequence[ExtractionConfig],
    pred_extraction_target: Sequence[ExtractionConfig],
    aggregation_function: Callable[[list[float]], float] = max,
    fallback_mode: Literal["no_fallback", "first_match"] = "first_match",
    precision: int = 6,
    strict: bool = True,
    allow_set_relation_comp: bool = False,
) -> Callable[[list[str], list[str]], tuple[float, tuple[list, list]]]:
    """Build a sample-level metric closure.

    The returned callable takes ``(golds, predictions)`` - both lists of raw
    strings - parses each, verifies every prediction against every gold, and
    aggregates the per-prediction 0/1 scores.
    """

    def sample_level_fn(
        golds: list[str], predictions: list[str]
    ) -> tuple[float, tuple[list, list]]:
        parsed_golds = [
            parse(gold, gold_extraction_target, fallback_mode=fallback_mode)
            for gold in golds
        ]
        parsed_preds = [
            parse(pred, pred_extraction_target, fallback_mode=fallback_mode)
            for pred in predictions
        ]

        if any(len(g) == 0 for g in parsed_golds):
            raise ValueError(f"No gold targets found for at least one gold: {golds}")

        if not parsed_preds or all(len(p) == 0 for p in parsed_preds):
            return 0.0, (parsed_golds, parsed_preds)

        scores = [
            1.0
            if any(
                verify(
                    g,
                    p,
                    float_rounding=precision,
                    strict=strict,
                    allow_set_relation_comp=allow_set_relation_comp,
                )
                for g in parsed_golds
            )
            else 0.0
            for p in parsed_preds
        ]
        return aggregation_function(scores), (parsed_golds, parsed_preds)

    return sample_level_fn
